/* Apollo design pitch. Illustrative data only; no sensors, accounts, or network calls. */
const paths = {
  heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
  thermometer:'<path d="M9 14.8V5a3 3 0 0 1 6 0v9.8a5 5 0 1 1-6 0Z"/><path d="M12 8v9"/><circle cx="12" cy="18" r="1"/>',
  steps:'<ellipse cx="7" cy="8" rx="3" ry="5" transform="rotate(-20 7 8)"/><ellipse cx="17" cy="12" rx="3" ry="5" transform="rotate(20 17 12)"/><path d="m7 16 1 3m8 1-1 2"/>',
  home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',
  measure:'<path d="M4 4h5M4 4v5m16-5h-5m5 0v5M4 20h5m-5 0v-5m16 5h-5m5 0v-5M7 12h3l2-4 2 8 2-4h2"/>',
  journal:'<path d="M5 3h13v18H5a2 2 0 0 1 0-4h13M5 3a2 2 0 0 0-2 2v14m5-12h6m-6 4h6"/>',
  trend:'<path d="M4 4v16h17M7 15l5-5 4 2 5-7"/>',
  settings:'<path d="m10 3-1 3-3 1-3 3 2 3-1 3 3 2 3-1 3 3 3-2 1-3 3-2-1-4-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  back:'<path d="m15 5-7 7 7 7"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  up:'<path d="M12 20V4m-6 6 6-6 6 6"/>',
  check:'<path d="m5 12 4 4L20 5"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',
  shield:'<path d="m12 2 9 4v7c0 5-9 9-9 9s-9-4-9-9V6Z"/><path d="m8 12 3 3 5-6"/>',
  camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3Z"/><circle cx="12" cy="13" r="4"/>',
  flash:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v7l4 2"/>',
  phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',
  speaker:'<path d="m3 9 4 0 5-4v14l-5-4H3Zm13-1c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',
  wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0m-4 4h.01"/>',
  offline:'<path d="m2 2 20 20M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0m-4 4h.01"/>',
  signal:'<path d="M4 20v-4m5 4v-8m5 8V8m5 12V4"/>',
  leaf:'<path d="M20 3C6 1 1 11 5 17s15 1 15-14ZM4 21l11-12"/>',
  edit:'<path d="m15 4 5 5M4 20l1-6L17 2l5 5L10 19Z"/>',
  plus:'<path d="M12 4v16M4 12h16"/>',
  smile:'<circle cx="12" cy="12" r="9"/><path d="M8 9h.01M16 9h.01M8 14q4 5 8 0"/>',
  neutral:'<circle cx="12" cy="12" r="9"/><path d="M8 9h.01M16 9h.01M8 15h8"/>',
  sad:'<circle cx="12" cy="12" r="9"/><path d="M8 9h.01M16 9h.01M8 17q4-5 8 0"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
  airplane:'<path d="m22 2-7 20-3-10L2 9Zm-10 10L22 2"/>',
  power:'<path d="M12 2v10M6 5a9 9 0 1 0 12 0"/>',
  layers:'<path d="m12 3 10 5-10 5L2 8Zm-9 10 9 5 9-5M3 18l9 5 9-5"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.info}</svg>`;
const expressions = [
 {id:'hello',name:'Hello, you.',emotion:'Warm & welcoming',usage:'Welcome · Today · Journal',screen:'welcome'},
 {id:'happy',name:'You did it!',emotion:'Happy ^_^ eyes',usage:'Exam complete · Journal saved',screen:'temp-result'},
 {id:'calm',name:'Nice and steady.',emotion:'Quiet & relaxed',usage:'Hold still · Measuring · Cooling',screen:'hr-recording'},
 {id:'curious',name:'Ready together?',emotion:'A little curiosity',usage:'Preparation · Permissions · Setup',screen:'temp-intro'},
 {id:'thinking',name:'One little moment.',emotion:'Thoughtful & focused',usage:'Checking signal · Analysis · Trends',screen:'hr-analysis'},
 {id:'encouraging',name:'We’ve got this.',emotion:'A reassuring wink',usage:'Retry · Interrupted · Unavailable',screen:'hr-weak'}
];
const expressionMap = {
 welcome:'hello',privacy:'calm',profile:'curious',permissions:'curious',
 today:'hello',measure:'curious',activity:'hello',journal:'hello','journal-new':'curious',
 trends:'thinking','heart-detail':'thinking',companion:'hello',
 'temp-intro':'curious','temp-ready':'curious','temp-cooling':'calm','temp-prehold':'calm',
 'temp-contact':'calm','temp-analysis':'thinking','temp-result':'happy','temp-reference':'curious',
 'temp-unreliable':'encouraging','hr-intro':'curious','temp-first':'thinking',
 'camera-permission':'curious','hr-coverage':'thinking','hr-settling':'calm','hr-recording':'calm',
 'hr-analysis':'thinking','hr-result':'happy','hr-weak':'encouraging','hr-reference':'curious',
 'today-empty':'hello',offline:'calm',unsupported:'encouraging','camera-denied':'calm',
 interrupted:'encouraging','journal-saved':'happy',settings:'hello','data-privacy':'calm',
 export:'curious','delete-confirm':'calm'
};
let renderingScreen='welcome';
const face = (mood='hello',cls='') => {
 const path=`assets/expressions/apollo-${mood}.png`;
 const src=window.apolloAssets?.[path] || path;
 return `<img class="apollo-face ${cls}" src="${src}" alt="Apollo — ${expressions.find(e=>e.id===mood).emotion.toLowerCase()}">`;
};
const mascot = (cls='') => face(expressionMap[renderingScreen] || 'hello',cls);
const btn = (text,to,kind='primary') => `<button class="${kind}" data-go="${to}">${text}${kind==='primary'?icon('arrow'):''}</button>`;
const chip = (text,type='') => `<span class="chip ${type}">${icon(type==='warn'?'info':'check')}${text}</span>`;
const card = (content,cls='') => `<div class="card ${cls}">${content}</div>`;
const heading = (title,subtitle='',overline='') => `<div class="page-heading">${overline?`<div class="overline">${overline}</div>`:''}<div class="heading-row"><h1>${title}</h1>${['Today','Measure','Journal','Trends'].includes(title)?`<span class="heading-tools">${mascot('heading-face')}<button class="icon-circle" data-go="settings" aria-label="Settings">${icon('settings')}</button></span>`:''}</div>${subtitle?`<p>${subtitle}</p>`:''}</div>`;
const back = (label,to='measure') => `<div class="back-row"><button data-go="${to}">${icon('back')}${label}</button>${mascot('back-face')}</div>`;
const row = (title,value,detail='',name='') => `<div class="quiet-row"><div class="leading">${name?icon(name):''}<div><b>${title}</b>${detail?`<small>${detail}</small>`:''}</div></div><span>${value}</span></div>`;
const feature = (name,title,text) => `<div class="feature-row">${icon(name)}<div><h3>${title}</h3><p>${text}</p></div></div>`;
const stepTag = (n,label,total=3) => `<div class="step-tag"><span>${label}</span>${Array.from({length:total},(_,i)=>`<i class="${i<n?'done':''}"></i>`).join('')}</div>`;
const timer = (time,caption,offset=260) => `<div class="timer-ring" style="--offset:${offset}"><svg viewBox="0 0 220 220" aria-label="${time} remaining"><circle cx="110" cy="110" r="100"/><circle class="progress" cx="110" cy="110" r="100"/></svg><div class="center"><div class="hero-number">${time}</div><small>${caption}</small></div></div>`;
const wave = () => `<svg class="pulse-wave" viewBox="0 0 300 90" role="img" aria-label="Illustrative optical pulse waveform"><path d="M0 65Q6 66 11 60C17 53 20 16 25 14C30 14 30 39 35 43C40 48 42 41 45 44C48 48 48 65 58 65Q64 66 69 60C75 53 78 16 83 14C88 14 88 39 93 43C98 48 100 41 103 44C106 48 106 65 116 65Q122 66 127 60C133 53 136 16 141 14C146 14 146 39 151 43C156 48 158 41 161 44C164 48 164 65 174 65Q180 66 185 60C191 53 194 16 199 14C204 14 204 39 209 43C214 48 216 41 219 44C222 48 222 65 232 65Q238 66 243 60C249 53 252 16 257 14C262 14 262 39 267 43C272 48 274 41 277 44C280 48 280 65 290 65L300 65"/></svg>`;
function chart(kind='heart',large=false){
 const data = kind==='temp'?[0,.07,.14,.22,.29,.38,.46,.54,.63]:[73,76,72,68,70,66,71,68,72,69,73,70,72,70];
 const pts=data.map((v,i)=>`${28+i*(238/(data.length-1))},${kind==='temp'?95-v/.6*70:95-(v-50)/40*70}`).join(' ');
 return `<svg class="mini-chart ${large?'large':''}" viewBox="0 0 290 130" role="img" aria-label="Illustrative ${kind==='temp'?'phone warming curve, degrees Celsius over 90 seconds':'heart rate trend, beats per minute'}"><path class="gridline" d="M26 25H270M26 60H270M26 95H270"/>${kind==='heart'?'<rect x="27" y="40" width="242" height="32" fill="var(--green-bg)" opacity=".7"/>':''}<polyline class="data-line" points="${pts}"/><text x="0" y="29">${kind==='temp'?'+.6':'90'}</text><text x="0" y="64">${kind==='temp'?'+.3':'70'}</text><text x="0" y="99">${kind==='temp'?'0':'50'}</text><text x="27" y="122">${kind==='temp'?'0 s':'Mon'}</text><text x="136" y="122">${kind==='temp'?'45 s':'Thu'}</text><text x="252" y="122">${kind==='temp'?'90 s':'Sun'}</text></svg>`;
}
const bars = () => `<div class="bar-chart" role="img" aria-label="Illustrative steps for Monday through Sunday: 4200, 5900, 5100, 7300, 6200, 6482; Sunday has no data yet">${[48,67,58,83,71,74,0].map(h=>`<div style="--height:${h}%"></div>`).join('')}</div><div class="chart-axis"><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span></div>`;
const titleRow = (name,title,time='')=>`<div class="card-title"><span>${icon(name)}${title}</span><small>${time}</small></div>`;
const examArt = () => `<div class="exam-art">${mascot()}<div class="mini-device" aria-label="Phone illustration"></div></div>`;
const voice = () => `<div class="voice-badge">${icon('speaker')}Voice guidance is on</div>`;
const foot = text => `<p class="footnote">${text}</p>`;
const protocols = lines => `<ol class="protocol-list">${lines.map(t=>`<li><span>${t}</span></li>`).join('')}</ol>`;
const stepsCard = () => card(`${titleRow('steps','Steps','TODAY')}<div class="small-value">6,482 <span>steps</span></div><div class="progress-track" style="--progress:65%"><i></i></div><small>Since first open today</small>`);
const groups = [
 {id:'start',title:'A friendly first hello',subtitle:'Brand & onboarding'},
 {id:'daily',title:'Your day, at a glance',subtitle:'The everyday experience'},
 {id:'temperature',title:'A guided temperature exam',subtitle:'Prepare → hold → capture → result'},
 {id:'heart',title:'A little closer to your heartbeat',subtitle:'Position → steady → capture → result'},
 {id:'care',title:'Care in the in-between',subtitle:'Empty, offline & recovery states'},
 {id:'settings',title:'Always in your hands',subtitle:'Preferences, privacy & data'}
];
const screens=[];
function add(id,title,group,content,opts={}){screens.push({id,title,group,content,...opts});}

add('welcome','Welcome','start',()=>`<div class="welcome"><div class="brand-name">apollo</div><div class="onboard-hero">${mascot()}</div><h1>A little more<br>in tune.</h1><p>Meet your everyday health companion.<br>Check in, notice patterns, feel more you.</p>${btn('Say hello','privacy')}<small>No account needed. Just you.</small><div class="step-dots"><i class="active"></i><i></i><i></i></div></div>`,{note:'Apollo carries the brand in a generous opening moment. The waving pose doubles as the app icon.'});
add('privacy','Privacy introduction','start',()=>`${back('Welcome','welcome')}<div class="onboard-art"><div class="large-icon">${icon('shield')}</div></div>${heading('Your health.<br>Your space.','You decide what stays private and what you share.')}${feature('phone','Stored on this phone','Measurements and journal entries work offline.')}${feature('lock','No account. No cloud sync.','Your health history lives with you.')}${feature('info','A choice before you chat','Apollo’s online assistant only gets the context you choose to send.')}${btn('Sounds good','profile')}<div class="step-dots"><i></i><i class="active"></i><i></i></div>`,{note:'Matches the local-first architecture. Network access is isolated to the proposed companion experience.'});
add('profile','Make it yours','start',()=>`${back('Privacy','privacy')}<div class="onboard-art">${mascot()}</div>${heading('Let’s make<br>this yours.','A few little details. All optional.')}<label class="field">What should Apollo call you?<input placeholder="Your first name" value="Alex" autocomplete="off"></label><label class="field">Daily step goal<select><option>10,000 steps</option><option>8,000 steps</option><option>6,000 steps</option></select></label><label class="field">Temperature unit<select><option>Celsius · °C</option><option>Fahrenheit · °F</option></select></label>${btn('Continue','permissions')}${btn('Skip for now','permissions','text-action')}`,{note:'Proposed onboarding collects only a name and preferences, without requiring a health profile or account.'});
add('permissions','Permission choices','start',()=>`${back('About you','profile')}${heading('A little help<br>from your phone.','Enable the things you want to use.')}${card(`${row('Movement',`<button class="toggle" role="switch" aria-checked="true" aria-label="Movement permission" data-action="toggle"></button>`,'Count your steps','steps')}${row('Camera',chip('Ask later','neutral'),'Only for heart-rate exams','camera')}${row('Voice guidance',`<button class="toggle" role="switch" aria-checked="true" aria-label="Voice guidance" data-action="toggle"></button>`,'Hear each exam step','speaker')}`)}${card(`${icon('info')}<h3 style="margin-top:10px">Temperature availability</h3><p>Depends on your phone’s sensors and research setup. Apollo checks before you start.</p>`,'soft')}${foot('You can change these choices in Settings. This pitch simulates permissions; it does not request device access.')}${btn('Meet your Today','today')}`,{note:'Each permission has a specific purpose. The camera request occurs at the beginning of the heart-rate flow.'});

add('today','Today / home','daily',()=>`${heading('Today','','SATURDAY, OCTOBER 17')}<div style="margin:-9px 0 18px;font-size:12px;color:var(--muted)">Good morning, Alex. Here’s your day.</div><button class="card tappable" data-go="heart-detail">${titleRow('heart','Heart rate','9:32 AM')}<div class="metric-row"><div class="measure-value">72<span>bpm</span></div><svg class="spark" viewBox="0 0 126 48" aria-hidden="true"><path d="M0 34 10 32 17 36 24 22 31 26 39 15 47 24 56 20 64 27 73 14 81 22 89 17 98 22 107 11 116 19 126 16" fill="none" stroke="var(--coral)" stroke-width="2.4" stroke-linejoin="round"/></svg></div>${chip('Good signal')}</button><div class="two-col">${stepsCard()}<button class="card tappable" data-go="temp-result">${titleRow('thermometer','Temperature')}<div class="small-value">Check-in</div><small>Warming test recorded</small><div style="margin-top:12px">${chip('Research','neutral')}</div></button></div><button class="card tappable" data-go="activity">${row('Elevation change','+12 m · ≈ 4 floors','Since this screen opened','layers')}</button>${btn('Take a measurement','measure')}`,{nav:'today',note:'A data-first home: latest reading, quality, timestamp, activity, and a clear measurement action. No floating mascot.'});
add('measure','Measurement hub','daily',()=>`${heading('Measure','Small check-ins. A clearer picture.')}<button class="card soft tappable" data-go="temp-intro"><div class="overline" style="color:var(--coral-text)">YOUR GUIDED CHECK-IN</div><h2 style="margin:9px 0">Time for you.</h2><p style="max-width:220px">Temperature first, then heart rate.<br>Apollo walks you through it.</p><div style="margin-top:13px;font-size:11px;font-weight:600">Start check-in ${icon('arrow')}</div></button><div class="section-label">Choose a measurement</div><button class="card tappable" data-go="temp-intro">${titleRow('thermometer','Temperature','01')}<p>60 s preparation + 90 s contact</p><div style="margin-top:13px;display:flex;justify-content:space-between">${chip('Phone ready')}${icon('chevron')}</div></button><button class="card tappable" data-go="hr-intro">${titleRow('heart','Heart rate','02')}<p>20 s capture · camera + flash</p><div style="margin-top:13px;display:flex;justify-content:space-between">${chip('Last: 72 bpm','neutral')}${icon('chevron')}</div></button>${foot('Taking both? The temperature test comes first because the camera flash warms your phone.')}`,{nav:'measure',note:'The primary combined check-in solves the exam-order problem. Individual exams remain available.'});
add('activity','Activity detail','daily',()=>`${back('Today','today')}${heading('Your activity.','Your movement, at your pace.')}${card(`${titleRow('steps','Steps today')}<div class="measure-value">6,482<span>steps</span></div><div class="progress-track" style="--progress:65%"><i></i></div><small>65% of your 10,000 step goal</small>${bars()}`)}<div class="two-col">${card('<div class="overline">HEIGHT CHANGE</div><div class="small-value">+12 <span>m</span></div><small>Since opening</small>')}${card('<div class="overline">FLOOR ESTIMATE</div><div class="small-value">≈ 4</div><small>From barometer</small>')}</div>${foot('Steps count since first open today. Height change is relative to this session.')}`,{nav:'today',note:'The current prototype’s counters are session/day-baseline limited. The UI does not present them as complete imported activity history.'});
add('journal','Journal','daily',()=>`${heading('Journal','Your numbers tell part of the story.')}<button class="card soft tappable" data-go="journal-new"><div class="inline-apollo">${mascot()}<div><h3>What’s on your mind?</h3><p>A little check-in goes a long way.</p></div>${icon('plus')}</div></button><div class="section-label">Recent moments</div>${card('<div class="journal-date">TODAY · 9:35 AM</div><h3>Feeling pretty good</h3><p class="journal-note">A slow morning and a walk around the neighborhood. Ready for the day.</p><div class="tags"><span class="tag">Good energy</span><span class="tag">Walk</span></div>')}${card('<div class="journal-date">YESTERDAY · 8:10 PM</div><h3>A quieter kind of day</h3><p class="journal-note">Took it easy after a busy week. Glad I made a little time for myself.</p><div class="tags"><span class="tag">Rest</span><span class="tag">Okay</span></div>')}`,{nav:'journal',note:'Proposed v1 journal. The character appears inside an invitation, rather than covering app content.'});
add('journal-new','Journal composer','daily',()=>`${back('Journal','journal')}${heading('How are<br>you, really?','There’s no right answer.')}<div class="moods">${[['sad','Low'],['neutral','A little off'],['neutral','Okay'],['smile','Good'],['smile','Great']].map(([i,t])=>`<button data-action="mood" class="${t==='Good'?'active':''}" aria-pressed="${t==='Good'}">${icon(i)}${t}</button>`).join('')}</div><label class="field">A few words for today<textarea placeholder="What’s been on your mind?">A slow morning and a walk around the neighborhood. Ready for the day.</textarea></label><div class="section-label" style="font-size:12px">Add a little context</div><div class="tags">${['Good energy','Walk','Rest','Stress','Sleep','Something else'].map((t,i)=>`<button data-action="tag" aria-pressed="${i<2}" class="tag ${i<2?'active':''}">${t}</button>`).join('')}</div>${btn('Save this moment','journal-saved')}${foot('Your journal stays on this phone. You choose if an entry is shared with Apollo’s online assistant.')}`,{note:'Mood, text, and tags use lightweight input controls. In this pitch, saving demonstrates the confirmation state.'});
add('trends','Trends overview','daily',()=>`${heading('Trends','A little perspective on your week.')}<div class="range-tabs">${['Week','Month','Year'].map((x,i)=>`<button class="${i===0?'active':''}" data-action="range">${x}</button>`).join('')}</div><button class="card tappable" data-go="heart-detail">${titleRow('heart','Heart rate','THIS WEEK')}<div class="small-value">71<span> bpm average</span></div>${chart()}<small>Shaded area: your recent range</small></button>${card(`${titleRow('steps','Daily steps')}<div class="small-value">5,864<span> average</span></div>${bars()}`)}<small>Illustrative data · your personal history</small>`,{nav:'trends',note:'Proposed v1 trend screen. Chart ranges are personal history, not diagnostic thresholds.'});
add('heart-detail','Heart-rate history','daily',()=>`${back('Trends','trends')}${heading('Heart rate','','YOUR RECENT READINGS')}<div class="range-tabs">${['Day','Week','Month','Year'].map((x,i)=>`<button class="${i===1?'active':''}" data-action="range">${x}</button>`).join('')}</div>${card(`<div class="measure-value">71<span>bpm average</span></div>${chart()}<small>Your recent range · illustrative data</small>`)}<div class="section-label">Latest readings<button data-go="hr-intro">Measure</button></div>${card(`${row('Today, 9:32 AM','72 bpm','Good signal')}${row('Yesterday, 8:12 AM','69 bpm','Good signal')}${row('Thursday, 9:05 AM','73 bpm','Good signal')}`,'reading-list')}${foot('Camera pulse readings are check-ins, not continuous heart monitoring.')}`,{note:'A detail drilldown keeps provenance, timestamps, and signal quality close to the values.'});
add('companion','Apollo conversation','daily',()=>`${back('Today','today')}<div class="inline-apollo" style="margin-bottom:20px">${mascot()}<div><h2>A little perspective.</h2><p>Apollo · online assistant</p></div></div><div class="note-banner">You’re sharing today’s heart-rate reading and your latest journal entry.</div><div class="bubble user">What does my morning look like?</div><div class="bubble apollo">Your latest check-in was <b>72 bpm</b>, with a good signal. You also wrote that you had a slow morning and went for a walk.<br><br>Want to add a note about how you felt during the check-in?<span class="source">Based on: heart rate · 9:32 AM<br>Journal · 9:35 AM</span></div><button class="secondary" data-go="journal-new">Add a journal note</button><div class="composer"><input aria-label="Message Apollo" placeholder="Ask Apollo…"><button data-action="chat" aria-label="Send message">${icon('up')}</button></div>${foot('Example conversation. Apollo helps you reflect on your data; it does not diagnose.')}`,{note:'Companion is a dedicated surface reached through contextual links. No persistent bottom-right mascot.'});

add('temp-intro','Temperature / introduction','temperature',()=>`${back('Measure')}${heading('A gentle<br>temperature check.','Let Apollo guide you, one step at a time.')}${examArt()}${protocols(['<strong>Prepare for 60 seconds.</strong><br>Hold the phone by its corners, screen facing away.','<strong>Forehead contact for 90 seconds.</strong><br>Hold the screen flat against your forehead, sideways.','<strong>Listen for the finish.</strong><br>Voice cues guide you while you can’t see the screen.'])}${btn('Check my phone','temp-ready')}${foot('Research warming test. A calibrated body-temperature estimate is not available yet.')}`,{note:'Maps to FeverActivity.showIntro: 60-second pre-hold and 90-second screen-to-forehead contact.'});
add('temp-ready','Phone readiness','temperature',()=>`${back('Temperature','temp-intro')}${stepTag(1,'PREPARE')}${heading('Ready when<br>your phone is.','A steady phone helps make a useful reading.')}${card(`${row('Phone is cool',chip('Ready'),'28.4 °C · below 32 °C','thermometer')}${row('Temperature is steady',chip('Ready'),'Stable for 2 minutes','trend')}${row('Power is settled',chip('Ready'),'Unplugged · no recent changes','power')}${row('No recent camera flash',chip('Ready'),'No cooldown needed','flash')}`)}${card(`${feature('airplane','Turn on airplane mode','Reduce changes in phone activity.')}${feature('phone','Remove your case','Keep the screen clean and uncovered.')}${feature('speaker','Sound on','You’ll hear when to move and finish.')}`)}${btn('Begin 60-second preparation','temp-prehold')}`,{note:'Readiness reflects ThermalMonitor: drift, temperature, charging/power changes, and recent torch use.'});
add('temp-cooling','Cooling / blocked state','temperature',()=>`${back('Temperature','temp-intro')}${heading('A little pause.<br>A better reading.','The camera flash warmed your phone.')}${timer('~8','minutes to settle',400)}${card('<h3>Let your phone rest</h3><p>Leave it on a table. Apollo will recheck its temperature while this screen is open.</p>','soft')}${card(`${row('Phone temperature','33.1 °C')}${row('Status',chip('Cooling','warn'))}`)}<button class="primary" disabled>Waiting for a steady phone</button>${btn('Write a journal note','journal-new','text-action')}`,{note:'Blocked until ThermalMonitor actually reports READY. This approximate cooldown is example UI, not a promise of readiness after a fixed timer.'});
add('temp-prehold','60-second preparation','temperature',()=>`${back('Cancel','interrupted')}${stepTag(1,'STEP 1 OF 2')}${heading('Hold by the<br>corners.','Keep the screen facing away from you.')}${timer('0:42','of 60 seconds remaining',190)}<p class="countdown-note">Your phone is learning its own warmth.<br>You’re doing great.</p>${voice()}${card('<h3>Next: your forehead</h3><p>When you hear the cue, turn the phone sideways and place the screen flat against your forehead.</p>')}${btn('Preview next step','temp-contact','text-action')}`,{note:'PREHOLD state: exactly 60 seconds. The preview step is a presentation control; native progression is timed.'});
add('temp-contact','90-second forehead contact','temperature',()=>`${face('calm','contact-face')}<div class="overline" style="color:#b7c5aa">STEP 2 OF 2 · FOREHEAD CONTACT</div><h2 style="margin-top:22px">Stay just like that.</h2>${timer('1:08','of 90 seconds remaining',150)}<p>Keep the screen flat against your forehead.<br>Apollo will tell you when you’re done.</p>${voice()}<div class="locked">${icon('lock')} Touch is locked during this step</div><small style="margin-top:18px">Use the system Back button to cancel.</small>`,{contact:true,note:'The live contact screen is dark and touch-locked, matching FeverActivity. Voice and vibration carry the experience. Use the pitch arrows to preview the next state.'});
add('temp-analysis','Temperature / analysis','temperature',()=>`${back('Temperature','temp-intro')}<div class="spinner-art">${mascot()}</div><div class="center"><h2>All done holding.</h2><p style="margin-top:15px">You can lower your phone.<br>We’re checking your warming curve.</p>${voice()}</div>${btn('Preview result','temp-result','text-action')}`,{note:'ANALYZING state follows capture. Illustration stays quiet; no fabricated live temperature value.'});
add('temp-result','Temperature / result','temperature',()=>`${back('Measure')}${heading('Check-in complete.','','FOREHEAD WARMING TEST')}<div class="result-hero"><div class="result-measure"><div><div class="hero-number" style="font-size:64px">+0.42</div><div class="hero-unit">°C / min · corrected warming rate</div></div>${face('happy')}</div>${chip('Steady phone')}<p>Saved on this phone · 9:28 AM</p></div>${card(`${titleRow('trend','Your warming curve')}${chart('temp')}<small>Phone temperature change during contact</small>`)}<div class="note-banner">A research warming signal. This is not a body-temperature or fever reading.</div>${btn('Add a thermometer reading','temp-reference','secondary')}${btn('Continue to heart rate','hr-intro')}`,{note:'Matches FeverAnalysis.correctedCPerMin. There is no fabricated 36.8 °C phone estimate.'});
add('temp-reference','Thermometer reference','temperature',()=>`${back('Result','temp-result')}${heading('A real-world<br>reference.','Pair this test with your thermometer, if you have one.')}${card(`${titleRow('thermometer','Your warming test')}<div class="small-value">+0.42 <span>°C / min</span></div><small>Today · 9:28 AM</small>`)}<label class="field">Thermometer reading<input type="number" step="0.1" inputmode="decimal" placeholder="e.g. 36.8" value="36.8" aria-label="Thermometer temperature in Celsius"></label><div class="range-tabs"><button class="active" data-action="unit">°C</button><button data-action="unit">°F</button></div>${card('<h3>Why add a reference?</h3><p>Paired readings help the team calibrate the research model. This number comes from your thermometer.</p>','sage')}${btn('Save reference','temp-result')}${btn('Skip this step','temp-result','text-action')}`,{note:'Maps to the optional ref_c field. This illustrative 36.8 °C is explicitly external, not a phone-derived body temperature.'});
add('temp-unreliable','Temperature / unreliable','temperature',()=>`${back('Measure')}${heading('Let’s try that<br>when it’s steadier.')}<div class="onboard-art">${mascot()}</div>${card(`${chip('Unreliable conditions','warn')}<h3 style="margin-top:14px">Your phone was still settling.</h3><p>Its own warmth changed during the test, so this session can’t give a dependable warming signal.</p>`,'amber')}${card('<h3>What you can do</h3><p>Rest the phone on a table and wait for the readiness check to turn green before trying again.</p>')}${btn('Check phone readiness','temp-ready')}${btn('Done for now','today','text-action')}`,{note:'An unreliable research session stays clearly labeled; no large result is shown as trustworthy.'});

add('hr-intro','Heart rate / introduction','heart',()=>`${back('Measure')}${heading('Find your<br>rhythm.','A quick pulse check, with your camera.')}${examArt()}${protocols(['<strong>Rest your hand on a table.</strong><br>Sit comfortably and keep still.','<strong>Cover the rear camera and flash.</strong><br>Use your fingertip and press gently.','<strong>Hold for 20 seconds.</strong><br>We’ll start once your signal is steady.'])}${btn('Let’s begin','temp-first')}${foot('The flash can feel warm. Lift your finger at any time if it feels uncomfortable.')}`,{note:'Matches HeartRateActivity: camera + flash, light pressure, full coverage, and 20 seconds of steady capture.'});
add('temp-first','Temperature-first prompt','heart',()=>`<div class="underlay">${heading('Find your<br>rhythm.')}${examArt()}${protocols(['Rest your hand.','Cover the camera and flash.','Hold still for 20 seconds.'])}</div><div class="bottom-sheet"><div class="inline-apollo">${mascot()}<h2>Temperature<br>check too?</h2></div><p>Let’s do that first. The camera light warms your phone and can affect the warming test.</p>${btn('Temperature first','temp-intro')}${btn('Just heart rate','camera-permission','secondary')}</div>`,{note:'Preserves the existing maybeTemperatureFirst choice in a calmer bottom sheet.'});
add('camera-permission','Camera permission','heart',()=>`${back('Heart rate','hr-intro')}${heading('A little light<br>on your pulse.','Your camera sees tiny changes in light through your fingertip.')}<div class="permission-dialog">${icon('camera')}<h2>Allow Apollo<br>to use your camera?</h2><p>Only during a heart-rate exam.<br>Camera frames are processed on your phone.</p>${btn('Allow during this exam','hr-coverage')}${btn('Not now','camera-denied','text-action')}</div>${foot('Design representation of the system permission request. No camera access is requested by this pitch.')}`,{note:'Shows when the OS permission should appear. Native Android renders the real system dialog.'});
add('hr-coverage','Finger placement','heart',()=>`${back('Cancel','interrupted')}${stepTag(1,'FIND YOUR SIGNAL')}${heading('A little to<br>the left.','Cover the camera lens and flash completely.')}<div class="signal-preview">${Array.from({length:25},(_,i)=>`<span class="${i%5===4?'bad':''}"></span>`).join('')}</div><div class="signal-legend"><span>80% covered</span><span>Light at the right edge</span></div>${card('<h3>Easy does it.</h3><p>Move your fingertip slightly. Press lightly; squeezing can hide your pulse.</p>','soft')}${foot('Recording starts automatically when the whole view is covered and stable.')}${btn('Preview good coverage','hr-settling','text-action')}`,{note:'Based on CoverageView’s tiled coverage and directional hints. Uncovered areas get a non-color-only label.'});
add('hr-settling','Signal settling','heart',()=>`${back('Cancel','interrupted')}${stepTag(1,'FIND YOUR SIGNAL')}${heading('That’s the spot.','Keep a gentle, steady touch.')}<div class="signal-preview">${Array.from({length:25},()=>'<span></span>').join('')}</div><div class="signal-legend"><span>100% covered</span>${chip('Covered')}</div>${card('<h3>Finding a steady signal…</h3><p>Hold still while the camera settles. Recording will begin on its own.</p>','sage')}${voice()}${btn('Preview recording','hr-recording','text-action')}`,{note:'SETTLING is distinct from camera coverage. The real camera waits for a stable, locked exposure before capture.'});
add('hr-recording','20-second heart-rate capture','heart',()=>`${back('Cancel','interrupted')}${stepTag(2,'RECORDING')}${heading('A little stillness.<br>That’s all.','Keep your finger lightly in place.')}${timer('0:12','of 20 seconds remaining',380)}${card(`${titleRow('heart','Your pulse','LIVE')}${wave()}<div style="display:flex;justify-content:space-between">${chip('Full coverage')}<small>Hold still</small></div>`)}${voice()}${btn('Preview result check','hr-analysis','text-action')}`,{note:'20-second capture uses an optical PPG waveform, not an ECG illustration. BPM appears only after analysis.'});
add('hr-analysis','Heart rate / analysis','heart',()=>`${back('Heart rate','hr-intro')}<div class="spinner-art">${mascot()}</div><div class="center"><h2>You can lift<br>your finger.</h2><p style="margin-top:15px">Checking your signal and counting beats.<br>Just a moment.</p></div>${btn('Preview result','hr-result','text-action')}`,{note:'Camera and flash are stopped before analysis. The phone then enters the thermal cooldown window.'});
add('hr-result','Heart rate / result','heart',()=>`${back('Measure')}${heading('Hello, heartbeat.','','YOUR PULSE CHECK')}<div class="result-hero"><div class="result-measure"><div><div class="hero-number">72</div><div class="hero-unit">beats per minute</div></div>${face('happy')}</div>${chip('Good signal')}<p>20-second capture · saved at 9:32 AM</p></div>${card(`${titleRow('heart','Your pulse waveform')}${wave()}<small>Illustrative optical pulse</small>`)}<div class="note-banner">A moment in time. Add a journal note to remember how you felt.</div>${btn('Add a watch reference','hr-reference','secondary')}${btn('Done','today')}`,{note:'The successful report keeps signal quality and measurement context prominent. No diagnostic label or fabricated normal range.'});
add('hr-weak','Weak signal / retry','heart',()=>`${back('Measure')}${heading('Let’s give it<br>another moment.')}<div class="result-hero"><div class="result-measure"><div><div class="hero-number" style="color:var(--muted)">—</div><div class="hero-unit">No reliable reading</div></div>${face('encouraging')}</div>${chip('Weak signal · retake','warn')}</div>${card('<h3>Your finger may have moved.</h3><p>Apollo couldn’t separate a clear pulse from the noise this time.</p>','amber')}${protocols(['Rest your hand on a table.','Cover both the lens and flash.','Use a light touch and hold still.'])}${btn('Try again','hr-coverage')}${btn('Done for now','today','text-action')}`,{note:'Matches the POOR verdict in HeartRateActivity: never show an unreliable BPM number large.'});
add('hr-reference','Watch comparison','heart',()=>`${back('Result','hr-result')}${heading('A second<br>point of view.','Add the watch reading you saw during your pulse check.')}${card(`${titleRow('heart','Apollo reading')}<div class="measure-value">72<span>bpm</span></div>${chip('Good signal')}`)}<label class="field">Your watch reading<input type="number" inputmode="numeric" value="70" placeholder="e.g. 70" aria-label="Watch reading in beats per minute"></label>${card('<div class="overline">EXAMPLE COMPARISON</div><div class="small-value">+2 <span>bpm difference</span></div><p>Apollo 72 · Watch 70</p>','sage')}${btn('Save comparison','hr-result')}${btn('Skip this step','hr-result','text-action')}${foot('Optional comparison for the research prototype. Your watch value is entered manually.')}`,{note:'Matches ref_bpm entry. The prototype supports manually comparing the camera estimate with a Fitbit.'});

add('today-empty','Today / first reading','care',()=>`${heading('Today','','GOOD MORNING, ALEX')}<div class="center">${mascot('empty-mascot')}<h2>Your story<br>starts here.</h2><p style="margin-top:12px">Your readings will appear here<br>after your first check-in.</p></div>${btn('Take your first measurement','measure')}<div class="section-label">For now, a little context</div>${card('<h3>How are you feeling?</h3><p>Start with a journal note. No sensors needed.</p>')}${btn('Add a journal moment','journal-new','secondary')}`,{nav:'today',note:'An empty home does not fabricate health values. Apollo makes the first step approachable.'});
