add('unsupported','Temperature unavailable','care',()=>`${back('Measure')}${heading('This phone needs<br>a little setup.')}<div class="onboard-art"><div class="large-icon">${icon('phone')}</div></div>${card('<h3>Temperature isn’t available yet.</h3><p>The research warming test needs compatible sensors and device setup before it can run.</p>','amber')}${card('<h3>You can still check in.</h3><p>Heart rate, your journal, and available activity sensors can be used independently.</p>')}${btn('Try heart rate','hr-intro')}${btn('View device details','settings','secondary')}`,{note:'UNSUPPORTED sensor/setup state. Technical setup stays in device details, away from the everyday measurement journey.'});
add('camera-denied','Camera access denied','care',()=>`${back('Heart rate','hr-intro')}${heading('Your camera.<br>Your choice.')}<div class="onboard-art"><div class="large-icon">${icon('camera')}</div></div>${card('<h3>Camera access is off.</h3><p>Apollo needs the camera and flash to check your pulse. You can enable access in your phone’s app settings.</p>','soft')}${btn('View permission settings','settings')}${btn('Go back to Today','today','secondary')}${foot('No camera access is needed to use your journal or view saved readings.')}`,{note:'Permission denial has a clear route to settings and a route back to the rest of the app.'});
add('interrupted','Exam interrupted','care',()=>`${back('Measure')}${heading('We paused<br>your check-in.')}<div class="onboard-art">${mascot()}</div>${card('<h3>Let’s start fresh.</h3><p>The exam stopped before it finished. A new capture helps keep your result consistent.</p>','soft')}${btn('Choose an exam','measure')}${btn('Back to Today','today','secondary')}${foot('The native prototype cancels an active exam when you leave the app or press Back.')}`,{note:'Represents onPause and Back cancellation in both activities, without claiming an incomplete capture is a valid result.'});
add('journal-saved','Journal / saved','care',()=>`${back('Journal','journal')}<div class="check-big expression-done">${face('happy')}</div><div class="center"><h1>A little moment,<br>kept.</h1><p style="margin-top:14px">Your journal entry is saved<br>on this phone.</p></div>${card('<div class="journal-date">TODAY · 9:35 AM</div><h3>Feeling good</h3><p class="journal-note">A slow morning and a walk around the neighborhood. Ready for the day.</p><div class="tags"><span class="tag">Good energy</span><span class="tag">Walk</span></div>')}${btn('Back to my journal','journal')}${btn('Reflect with Apollo','companion','secondary')}`,{note:'Proposed local-save confirmation. All data in this pitch is illustrative; the design does not write to the native app.'});

add('settings','Settings','settings',()=>`${back('Today','today')}${heading('Make yourself<br>at home.')}<div class="section-label">Your preferences</div>${card(`${row('Temperature units','°C','Celsius','thermometer')}${row('Voice guidance','<button class="toggle" role="switch" aria-checked="true" data-action="toggle" aria-label="Toggle voice guidance"></button>','Spoken exam cues','speaker')}${row('Appearance','System','Light and dark','phone')}`)}<div class="section-label">Your phone & data</div>${card(`<button class="tappable" style="background:none;padding:0" data-go="data-privacy">${row('Privacy & permissions',icon('chevron'),'Camera, movement, assistant','shield')}</button><button class="tappable" style="background:none;padding:0" data-go="export">${row('Export my data',icon('chevron'),'Readings and journal','download')}</button>${row('Device compatibility','Pixel 4','Research sensor setup','phone')}`)}<div class="inline-apollo" style="padding:12px 4px">${mascot()}<div><h3>Apollo</h3><p>A little more in tune.</p><small>Research prototype · v0.1</small></div></div>`,{note:'Proposed settings entry point. Detailed raw logs and development configuration remain outside normal exam screens.'});
add('data-privacy','Privacy & data','settings',()=>`${back('Settings','settings')}${heading('You’re in<br>control.','Your information belongs with you.')}${card(`${row('Camera','<button class="toggle" role="switch" aria-checked="true" data-action="toggle" aria-label="Camera access"></button>','During pulse checks only','camera')}${row('Movement','<button class="toggle" role="switch" aria-checked="true" data-action="toggle" aria-label="Movement access"></button>','Step counting','steps')}${row('Share chat context','<button class="toggle off" role="switch" aria-checked="false" data-action="toggle" aria-label="Share assistant context"></button>','Ask before sending','lock')}`)}${card('<h3>On this phone</h3><p>Health readings and journal entries stay local. There’s no account or cloud sync.</p>','sage')}${btn('Export a copy','export','secondary')}<button class="text-action" style="color:var(--coral-text)" data-go="delete-confirm">Delete all my data</button>${foot('Permission controls are concepts. In the real app, system settings are the source of truth.')}`,{note:'Data deletion is gated behind a dedicated confirmation screen. This mockup never touches native data.'});
add('export','Export data','settings',()=>`${back('Settings','settings')}${heading('Your story,<br>to keep.','Choose what goes in your export.')}${card(`${row('Measurements','<button class="toggle" role="switch" aria-checked="true" data-action="toggle" aria-label="Include measurements"></button>','Readings and quality labels','heart')}${row('Journal entries','<button class="toggle" role="switch" aria-checked="true" data-action="toggle" aria-label="Include journal"></button>','Notes, mood, and tags','journal')}${row('Raw sensor sessions','<button class="toggle off" role="switch" aria-checked="false" data-action="toggle" aria-label="Include raw sessions"></button>','For research and analysis','trend')}`)}${card('<h3>Only share with people you choose.</h3><p>An export can contain personal health information. Apollo creates a file for you to save or share.</p>','soft')}<button class="primary" data-action="export">Download sample export ${icon('download')}</button>${foot('Pitch demo: downloads a small file of fictional sample data. No real health records are accessed.')}`,{note:'Proposed export UI. The demonstration download is clearly labeled and contains only synthetic data.'});
add('delete-confirm','Delete confirmation','settings',()=>`${back('Privacy','data-privacy')}${heading('A fresh start?')}<div class="onboard-art"><div class="large-icon" style="background:var(--soft);color:var(--coral-text)">${icon('trash')}</div></div>${card('<h3>Delete everything on this phone?</h3><p>This removes measurements, raw sessions, and journal entries. There’s no cloud backup to restore from.</p>','soft')}${btn('Keep my data','data-privacy')}<button class="secondary" data-action="delete-demo" style="color:var(--coral-text)">Confirm deletion · demo only</button>${foot('This design prototype contains sample data only and cannot delete your app’s records.')}`,{note:'Explicit destructive-action confirmation, with keeping data as the primary action.'});

const byId = id => screens.find(s=>s.id===id);
function phoneHTML(id,interactive=false,dark=false){
 const s=byId(id); if(!s)throw new Error(`Unknown screen: ${id}`);
 renderingScreen=id;
 const nav=s.nav?`<nav class="bottom-nav" aria-label="App navigation">${[['today','home','Today'],['measure','measure','Measure'],['journal','journal','Journal'],['trends','trend','Trends']].map(([target,i,t])=>`<button data-go="${target}" class="${s.nav===target?'active':''}" ${s.nav===target?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav>`:'';
 let content=s.content();
 // Let a prominent, contextual face take precedence over a second face in the header.
 if((content.match(/class="apollo-face /g)||[]).length>1){
  content=content.replace(/<img class="apollo-face (?:back-face|heading-face)"[^>]*>/g,'');
 }
 return `<article class="phone ${s.nav?'has-nav':''} ${s.contact?'contact-mode':''} ${interactive?'interactive':''} ${dark?'dark':''}" data-screen="${id}" aria-label="${s.title}"><div class="statusbar"><span>9:41</span><span class="status-icons">${icon('signal')}${icon('wifi')}<i class="battery"></i></span></div><div class="screen">${content}</div>${nav}<div class="home-handle"></div></article>`;
}
let activeScreen='today';
let dark=false;
let previousFocus=null;
const dialog=document.getElementById('prototype');
function fitPrototype(){
 const wrap=document.getElementById('prototype-phone');
 const scale=Math.min(1,(innerWidth-40)/360);
 wrap.style.width=`${360*scale}px`;
 wrap.style.height=`${780*scale}px`;
 const phone=wrap.querySelector('.phone');
 if(phone){phone.style.transform=`scale(${scale})`;phone.style.transformOrigin='top left';}
}
function openScreen(id){
 const s=byId(id);if(!s)return;
 activeScreen=id;
 document.getElementById('prototype-title').textContent=s.title;
 document.getElementById('prototype-kind').textContent=`${String(screens.indexOf(s)+1).padStart(2,'0')} / ${screens.length} · interactive design concept`;
 document.getElementById('prototype-phone').innerHTML=phoneHTML(id,true,dark);
 fitPrototype();
 document.getElementById('prototype-note').textContent=s.note;
 if(!dialog.open){previousFocus=document.activeElement;dialog.showModal();}
}
function closeScreen(){dialog.close();previousFocus?.focus();}
function atlas(){
 document.getElementById('hero-phones').innerHTML=phoneHTML('today')+phoneHTML('welcome');
 document.getElementById('expression-grid').innerHTML=expressions.map((e,i)=>`<button class="expression-tile" data-open="${e.screen}"><span class="expression-index">0${i+1} / ${e.emotion}</span>${face(e.id)}<h3>${e.name}</h3><p>${e.usage}</p><span class="expression-preview">See it on screen ↗</span></button>`).join('');
 document.getElementById('expression-examples').innerHTML=['temp-result','hr-recording','hr-weak'].map(id=>`<div class="expression-example"><div class="phone-holder" data-open="${id}">${phoneHTML(id)}</div><h3>${byId(id).title}</h3></div>`).join('');
 document.getElementById('filters').innerHTML=[['all','All screens'],...groups.map(g=>[g.id,{start:'Onboarding',daily:'Everyday',temperature:'Temperature',heart:'Heart rate',care:'Other states',settings:'Settings'}[g.id]])].map(([id,title],i)=>`<button data-filter="${id}" class="${i===0?'active':''}" aria-pressed="${i===0}">${title}</button>`).join('');
 document.getElementById('screen-groups').innerHTML=groups.map(g=>`<section class="screen-group" data-group="${g.id}"><div class="group-head"><h3>${g.title}</h3><span>${g.subtitle}</span></div><div class="screen-grid">${screens.filter(s=>s.group===g.id).map(s=>`<div class="screen-tile"><div class="phone-holder" data-open="${s.id}">${phoneHTML(s.id)}</div><div class="screen-caption"><span>${String(screens.indexOf(s)+1).padStart(2,'0')}</span><div><h4><button data-open="${s.id}" style="border:0;background:none;padding:0;font:inherit;text-align:left">${s.title} ↗</button></h4><p>${s.note}</p></div></div></div>`).join('')}</div></section>`).join('');
 const observer=new ResizeObserver(entries=>entries.forEach(e=>e.target.style.setProperty('--scale',e.contentRect.width/360)));
 document.querySelectorAll('.phone-holder').forEach(el=>observer.observe(el));
}
function action(el){
 const a=el.dataset.action;
 if(a==='toggle'){el.classList.toggle('off');el.setAttribute('aria-checked',String(!el.classList.contains('off')));}
 if(a==='mood'){el.parentElement.querySelectorAll('button').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});el.classList.add('active');el.setAttribute('aria-pressed','true');}
 if(a==='tag'){el.classList.toggle('active');el.setAttribute('aria-pressed',String(el.classList.contains('active')));}
 if(a==='range'||a==='unit'){el.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('active'));el.classList.add('active');const scope=el.closest('.screen');if(a==='range'){scope.querySelectorAll('.mini-chart,.bar-chart').forEach(c=>c.style.opacity=el.textContent==='Year'?.65:1);let note=scope.querySelector('.range-note');if(!note){note=document.createElement('p');note.className='footnote range-note';el.parentElement.after(note);}note.textContent=`${el.textContent} view selected · chart values are illustrative in this pitch.`;}else{const input=scope.querySelector('input[type=number]');if(input){input.value=el.textContent==='°F'?'98.2':'36.8';input.setAttribute('aria-label',`Thermometer temperature in ${el.textContent==='°F'?'Fahrenheit':'Celsius'}`);}}}
 if(a==='chat'){const field=el.parentElement.querySelector('input');if(!field.value.trim())return;const b=document.createElement('div');b.className='bubble user';b.textContent=field.value;el.parentElement.before(b);field.value='';const reply=document.createElement('div');reply.className='bubble apollo';reply.textContent='This is a design preview. In the app, Apollo would respond using only the context you chose to share.';el.parentElement.before(reply);}
 if(a==='export'){const data={demo:true,notice:'Fictional sample data for the Apollo UI pitch.',heart_rate:{bpm:72,quality:'GOOD',duration_seconds:20},forehead:{warming_rate_c_per_min:0.42,body_temperature_estimate:null},journal:{text:'A slow morning and a walk around the neighborhood.',mood:'Good'}};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='apollo-demo-export.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 if(a==='delete-demo'){openScreen('today-empty');document.getElementById('prototype-note').textContent='Demo reset shown. No real data was deleted.';}
}
document.addEventListener('click',event=>{
 const el=event.target;
 const filter=el.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter));});document.querySelectorAll('[data-group]').forEach(g=>g.hidden=filter.dataset.filter!=='all'&&g.dataset.group!==filter.dataset.filter);return;}
 const opener=el.closest('[data-open]');if(opener){openScreen(opener.dataset.open);return;}
 const go=el.closest('[data-go]');if(go){openScreen(go.dataset.go);return;}
 const command=el.closest('[data-action]');if(command)action(command);
});
document.getElementById('close-prototype').addEventListener('click',closeScreen);
document.getElementById('prev-screen').addEventListener('click',()=>openScreen(screens[(screens.findIndex(s=>s.id===activeScreen)+screens.length-1)%screens.length].id));
document.getElementById('next-screen').addEventListener('click',()=>openScreen(screens[(screens.findIndex(s=>s.id===activeScreen)+1)%screens.length].id));
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeScreen();}});
document.getElementById('dark-toggle').addEventListener('change',e=>{dark=e.target.checked;document.querySelectorAll('.phone').forEach(p=>p.classList.toggle('dark',dark));});
window.addEventListener('resize',fitPrototype);
const requested=new URLSearchParams(location.search);
if(requested.has('screen')){
 document.body.classList.add('screen-only');
 const root=document.createElement('div');root.id='export-root';root.innerHTML=phoneHTML(requested.get('screen'),false,requested.get('theme')==='dark');document.body.append(root);
}else atlas();
window.apolloPitch={screens:screens.map(({id,title,group,note})=>({id,title,group,note,expression:expressionMap[id]})),groups,expressions,expressionMap,openScreen,phoneHTML};
